INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('219255aa-a7cb-56cd-95fb-0bc99226634d', 'UK Transparency in Supply Chains etc. : A Practical', 'Transparency in Supply Chains etc. : A Practical Guide, 2015', 'This document provides guidance on: who is required to publish a statement, how to write a slavery and human trafficking statement and how to approve and publish the statement.', 'This document provides guidance on: who is required to publish a statement, how to write a slavery and human trafficking statement and how to approve and publish the statement.', 'This document provides guidance on: who is required to publish a statement, how to write a slavery and human trafficking statement and how to approve and publish the statement.', 'UK', 'circularity', 'in_force', '2015-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_17', ARRAY['uk', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1779c7d9-8dbd-5291-819d-427c592bf1a9', 'UK Modern Slavery Act 2015 (Section 54)', 'Modern Slavery Act 2015 (Section 54)', 'The Modern Slavery Act 2015 establishes legal frameworks to combat slavery, servitude, forced labor, and human trafficking. It enhances victim protection, strengthens law enforcement measures, and introduces corporate transparency requirements.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ac2ac22d-a719-5494-82e9-e9135a1dc7e1', 'UK Clear & Concise Developments in Narrative Reporting', 'Clear & Concise Developments in Narrative Reporting, 2015', 'The objectives of the Clear & Concise initiative are to encourage: communication that is focused on the needs of the audience; greater emphasis on the application of materiality; improvement in the relevance and readability of annual reports; and consideration of other channels for reporting information.', 'The objectives of the Clear & Concise initiative are to encourage: communication that is focused on the needs of the audience; greater emphasis on the application of materiality; improvement in the relevance and readability of annual reports; and consideration of other channels for reporting information.', 'The objectives of the Clear & Concise initiative are to encourage: communication that is focused on the needs of the audience; greater emphasis on the application of materiality; improvement in the relevance and readability of annual reports; and consideration of other channels for reporting information.', 'UK', 'climate', 'in_force', '2015-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_83', ARRAY['uk', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0fa188cb-632e-5f42-9cf8-6b46040de48a', 'UK Modern Slavery Act', 'Modern Slavery Act 2015', 'The Modern Slavery Act will give law enforcement the tools to fight modern slavery, ensure perpetrators can receive suitably severe punishments for these appalling crimes, enhance support and protection for victims, and ensure supply chain transparency.', 'The Modern Slavery Act will give law enforcement the tools to fight modern slavery, ensure perpetrators can receive suitably severe punishments for these appalling crimes, enhance support and protection for victims, and ensure supply chain transparency.', 'The Modern Slavery Act will give law enforcement the tools to fight modern slavery, ensure perpetrators can receive suitably severe punishments for these appalling crimes, enhance support and protection for victims, and ensure supply chain transparency.', 'UK', 'climate', 'in_force', '2015-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_97', ARRAY['sdg8', 'uk', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ac43720e-5daf-5b56-9af4-1611a7a27bf7', 'UK Public Contracts Regulations', 'The Public Contracts Regulations 2015', 'The Public Contracts Regulations 2015 in the United Kingdom outline rules for public procurement contracts, covering procedures, electronic procurement, contract performance, remedies, and miscellaneous obligations. It aims to ensure fair competition, transparency, and efficiency in government procurement processes, applicable to contracting authorities, economic operators, and other stakeholders.', 'The Public Contracts Regulations 2015 in the United Kingdom outline rules for public procurement contracts, covering procedures, electronic procurement, contract performance, remedies, and miscellaneous obligations. It aims to ensure fair competition, transparency, and efficiency in government procurement processes, applicable to contracting authorities, economic operators, and other stakeholders.', 'The Public Contracts Regulations 2015 in the United Kingdom outline rules for public procurement contracts, covering procedures, electronic procurement, contract performance, remedies, and miscellaneous obligations. It aims to ensure fair competition, transparency, and efficiency in government procurement processes, applicable to contracting authorities, economic operators, and other stakeholders.', 'UK', 'circularity', 'in_force', '2015-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/185_121', ARRAY['uk', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fc84ef88-db98-5b57-ae77-74a54fbd395d', 'UK Corporate Governance Code (formerly Combined Code)', 'UK Corporate Governance Code (formerly Combined Code), 2014', 'The Code sets out norms of good practice in relation to board leadership and effectiveness, remuneration, accountability and relations with shareholders. All companies with a Premium Listing of equity shares in the UK are required under the Listing Rules to report on how they have applied the Code in their annual report and accounts.', 'The Code sets out norms of good practice in relation to board leadership and effectiveness, remuneration, accountability and relations with shareholders. All companies with a Premium Listing of equity shares in the UK are required under the Listing Rules to report on how they have applied the Code in their annual report and accounts.', 'The Code sets out norms of good practice in relation to board leadership and effectiveness, remuneration, accountability and relations with shareholders. All companies with a Premium Listing of equity shares in the UK are required under the Listing Rules to report on how they have applied the Code in their annual report and accounts.', 'UK', 'climate', 'in_force', '2014-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_10', ARRAY['uk', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dade8ac0-eb43-5c7a-943f-632bccf60185', 'UK Reports on Payments to Governments', 'Reports on Payments to Governments, 2014', 'Companies to which the Regulations apply will need to prepare a report each year, with the first report being prepared for the first financial year beginning on or after January 1, 2015. For each financial year the report will need to specify: the government (and country) to which each payment has been made; the total amount of payments made to each government; the total amount per type of payment made to each government (e.g. taxes, royalty payments, dividends, license fees, rental fees etc.); and where payments have been attributed to a specific project, the total amount per type of payment made for each such project and the total amount of payments for each such project will need to be stated.', 'Companies to which the Regulations apply will need to prepare a report each year, with the first report being prepared for the first financial year beginning on or after January 1, 2015. For each financial year the report will need to specify: the government (and country) to which each payment has been made; the total amount of payments made to each government; the total amount per type of payment made to each government (e.g. taxes, royalty payments, dividends, license fees, rental fees etc.); and where payments have been attributed to a specific project, the total amount per type of payment made for each such project and the total amount of payments for each such project will need to be stated.', 'Companies to which the Regulations apply will need to prepare a report each year, with the first report being prepared for the first financial year beginning on or after January 1, 2015. For each financial year the report will need to specify: the government (and country) to which each payment has been made; the total amount of payments made to each government; the total amount per type of payment made to each government (e.g. taxes, royalty payments, dividends, license fees, rental fees etc.); and where payments have been attributed to a specific project, the total amount per type of payment made for each such project and the total amount of payments for each such project will need to be stated.', 'UK', 'climate', 'in_force', '2014-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_101', ARRAY['uk', 'mandatory', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c5d7b0ba-d70e-50fb-a96e-53ea04e2e81e', 'UK Reports on Payments to Governments Regulations', 'The Reports on Payments to Governments Regulations, 2014', 'They require large and publicly listed oil, gas, mining and logging companies registered (i.e. incorporated) in the UK to annually disclose the payments they make to governments on a country-by-country and project-by-project basis.', 'They require large and publicly listed oil, gas, mining and logging companies registered (i.e. incorporated) in the UK to annually disclose the payments they make to governments on a country-by-country and project-by-project basis.', 'They require large and publicly listed oil, gas, mining and logging companies registered (i.e. incorporated) in the UK to annually disclose the payments they make to governments on a country-by-country and project-by-project basis.', 'UK', 'climate', 'in_force', '2014-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_14', ARRAY['disclosure', 'mandatory', 'uk', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dacaaa14-16ba-534b-9826-d5e603f0e6df', 'UK Risk Management, Internal Control and Related Financial', 'Guidance on Risk Management, Internal Control and Related Financial and Business Reporting, 2014', 'This guidance revises, integrates and replaces the previous editions of the FRC''s Internal Control: Guidance to Directors (formerly known as the Turnbull Guidance) and the Going Concern and Liquidity Risk: Guidance for Directors of UK Companies and reflects changes made to the UK Corporate Governance Code in 2014.', 'This guidance revises, integrates and replaces the previous editions of the FRC''s Internal Control: Guidance to Directors (formerly known as the Turnbull Guidance) and the Going Concern and Liquidity Risk: Guidance for Directors of UK Companies and reflects changes made to the UK Corporate Governance Code in 2014.', 'This guidance revises, integrates and replaces the previous editions of the FRC''s Internal Control: Guidance to Directors (formerly known as the Turnbull Guidance) and the Going Concern and Liquidity Risk: Guidance for Directors of UK Companies and reflects changes made to the UK Corporate Governance Code in 2014.', 'UK', 'climate', 'in_force', '2014-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_81', ARRAY['guidance_frameworks', 'uk', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f0f50fbe-052b-5419-9a9a-5752a595ebd2', 'UK Lab insight report: Towards Clear & Concise Reporting', 'Lab insight report: Towards Clear & Concise Reporting, 2014', 'The 2013 reporting cycle brought significant change for UK companies. Companies now have an opportunity to make their accounts clearer and more concise, with some companies having already taken action in this direction. This insight report is based on observations that the Financial Reporting Lab (Lab) made during a review of 2013 year end reporting. It highlights progress made by companies towards clearer and more concise reporting and provides ideas on the process of change.', 'The 2013 reporting cycle brought significant change for UK companies. Companies now have an opportunity to make their accounts clearer and more concise, with some companies having already taken action in this direction. This insight report is based on observations that the Financial Reporting Lab (Lab) made during a review of 2013 year end reporting. It highlights progress made by companies towards clearer and more concise reporting and provides ideas on the process of change.', 'The 2013 reporting cycle brought significant change for UK companies. Companies now have an opportunity to make their accounts clearer and more concise, with some companies having already taken action in this direction. This insight report is based on observations that the Financial Reporting Lab (Lab) made during a review of 2013 year end reporting. It highlights progress made by companies towards clearer and more concise reporting and provides ideas on the process of change.', 'UK', 'climate', 'in_force', '2014-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_82', ARRAY['uk', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('df503b84-13c8-5d3b-be09-58c561ced495', 'UK Companies Act 2006 (Strategic Report and Directors’ Report)', 'The Companies Act 2006 (Strategic Report and Directors’ Report) Regulations', 'The 2013 amendment to the UK Companies Act 2006 introduces mandatory preparation of a strategic report by directors of companies, except for those qualifying under the small companies regime. Effective from October 1, 2013, the regulations aim to enhance transparency and accountability. Strategic reports are intended to provide shareholders with insights into the company’s business performance, risks, and future prospects. For quoted companies, additional requirements include disclosures on environmental impacts, employee matters, and diversity metrics such as the gender composition of boards, senior management, and employees. The regulations replace the previous business review requirement with a more structured reporting framework and mandate approval by the board of directors. Quoted companies must also disclose greenhouse gas emissions and methodologies used for calculation. The framework supports better corporate governance and aligns with the principles of the UK’s broader commitment to sustainability and responsible business practices.', 'The 2013 amendment to the UK Companies Act 2006 introduces mandatory preparation of a strategic report by directors of companies, except for those qualifying under the small companies regime. Effective from October 1, 2013, the regulations aim to enhance transparency and accountability. Strategic reports are intended to provide shareholders with insights into the company’s business performance, risks, and future prospects. For quoted companies, additional requirements include disclosures on environmental impacts, employee matters, and diversity metrics such as the gender composition of boards, senior management, and employees. The regulations replace the previous business review requirement with a more structured reporting framework and mandate approval by the board of directors. Quoted companies must also disclose greenhouse gas emissions and methodologies used for calculation. The framework supports better corporate governance and aligns with the principles of the UK’s broader commitment to sustainability and responsible business practices.', 'The 2013 amendment to the UK Companies Act 2006 introduces mandatory preparation of a strategic report by directors of companies, except for those qualifying under the small companies regime. Effective from October 1, 2013, the regulations aim to enhance transparency and accountability. Strategic reports are intended to provide shareholders with insights into the company’s business performance, risks, and future prospects. For quoted companies, additional requirements include disclosures on environmental impacts, employee matters, and diversity metrics such as the gender composition of boards, senior management, and employees. The regulations replace the previous business review requirement with a more structured reporting framework and mandate approval by the board of directors. Quoted companies must also disclose greenhouse gas emissions and methodologies used for calculation. The framework supports better corporate governance and aligns with the principles of the UK’s broader commitment to sustainability and responsible business practices.', 'UK', 'climate', 'in_force', '2013-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_1', ARRAY['sdg13', 'uk', 'sdg7', 'regulations', 'mandatory', 'sdg5', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0696e06d-31d1-545f-a82a-eceba59fd542', 'UK Companies Act 2006 (Strategic Report and Directors’Report) Regulations', 'The Companies Act 2006 (Strategic Report and Directors’Report) Regulations 2013', 'The amendments of the Companies Act 2006 on 17 July 2013, require all UK companies to produce a standalone Strategic Report which replaces the existing Business Review, further requirements are more company specific, including reporting on their strategy and business model, as well as on Greenhouse Gas emissions, human rights and diversity in the company.', 'The amendments of the Companies Act 2006 on 17 July 2013, require all UK companies to produce a standalone Strategic Report which replaces the existing Business Review, further requirements are more company specific, including reporting on their strategy and business model, as well as on Greenhouse Gas emissions, human rights and diversity in the company.', 'The amendments of the Companies Act 2006 on 17 July 2013, require all UK companies to produce a standalone Strategic Report which replaces the existing Business Review, further requirements are more company specific, including reporting on their strategy and business model, as well as on Greenhouse Gas emissions, human rights and diversity in the company.', 'UK', 'climate', 'in_force', '2013-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_20', ARRAY['sdg13', 'uk', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('be75cf18-ffd5-5ea9-9a13-ac180757747d', 'UK measuring and reporting Greenhouse Gas (GHG) emissions', 'Guidance on measuring and reporting Greenhouse Gas (GHG) emissions from freight transport operations, 2013', 'This guidance provides clear instructions on calculating the greenhouse gas (GHG) emissions from freight transport operations.', 'This guidance provides clear instructions on calculating the greenhouse gas (GHG) emissions from freight transport operations.', 'This guidance provides clear instructions on calculating the greenhouse gas (GHG) emissions from freight transport operations.', 'UK', 'climate', 'in_force', '2013-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_76', ARRAY['guidance_frameworks', 'sdg13', 'uk', 'sdg11', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6f397eee-afc9-5b1f-88ac-7bc79eb15e56', 'UK OMA: industrial installations regulated under the EPR', 'OMA: industrial installations regulated under the EPR - discharges to water, 2013', 'This document provides guidance to make an assessment of operators’ self-monitoring arrangements in an objective and consistent manner.', 'This document provides guidance to make an assessment of operators’ self-monitoring arrangements in an objective and consistent manner.', 'This document provides guidance to make an assessment of operators’ self-monitoring arrangements in an objective and consistent manner.', 'UK', 'governance', 'in_force', '2013-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_95', ARRAY['guidance_frameworks', 'other sustainability policy', 'uk', 'mandatory', 'sdg6']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4a797549-9b0b-5199-b8f9-a717b24f32fc', 'UK OMA: industrial installations regulated under the EPR', 'OMA: industrial installations regulated under the EPR - emissions to air, 2013', 'This document provides guidance to make an assessment of operators self-monitoring arrangements in an objective and consistent manner.', 'This document provides guidance to make an assessment of operators self-monitoring arrangements in an objective and consistent manner.', 'This document provides guidance to make an assessment of operators self-monitoring arrangements in an objective and consistent manner.', 'UK', 'climate', 'in_force', '2013-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_96', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'uk', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e25325c9-f511-5773-add1-580870f102fa', 'UK Stewardship Code', 'The UK Stewardship Code, 2012', 'The UK Stewardship Code aims to enhance the quality of engagement between asset managers and companies to help improve long-term risk-adjusted returns to shareholders.', 'The UK Stewardship Code aims to enhance the quality of engagement between asset managers and companies to help improve long-term risk-adjusted returns to shareholders.', 'The UK Stewardship Code aims to enhance the quality of engagement between asset managers and companies to help improve long-term risk-adjusted returns to shareholders.', 'UK', 'climate', 'in_force', '2012-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_23', ARRAY['uk', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('90a625af-af9b-58c7-8642-28f3b7e8655d', 'UK Corporate Governance Code', 'The UK Corporate Governance Code, 2012', 'The Code contains broad principles and more specific provisions. Listed companies are required to report on how they have applied the main principles of the Code, and either to confirm that they have complied with the Code''s provisions or - where they have not - to provide an explanation. Some of the provisions of the Code require disclosures to be made in order to comply with them. These are summarised in Schedule B to the Code.', 'The Code contains broad principles and more specific provisions. Listed companies are required to report on how they have applied the main principles of the Code, and either to confirm that they have complied with the Code''s provisions or - where they have not - to provide an explanation. Some of the provisions of the Code require disclosures to be made in order to comply with them. These are summarised in Schedule B to the Code.', 'The Code contains broad principles and more specific provisions. Listed companies are required to report on how they have applied the main principles of the Code, and either to confirm that they have complied with the Code''s provisions or - where they have not - to provide an explanation. Some of the provisions of the Code require disclosures to be made in order to comply with them. These are summarised in Schedule B to the Code.', 'UK', 'climate', 'in_force', '2012-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_66', ARRAY['guidance_frameworks', 'uk', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6c780212-8946-5c36-bfff-f2b5dc5f7888', 'UK Women on Boards', 'Women on Boards, 2011', 'This report recommends that UK listed companies in the FTSE 100 should be aiming for a minimum of 25% female board member representation by 2015. It also recommends for government that FTSE 350 companies should be setting their own, challenging targets. The report says that companies should set targets for 2013 and 2015 to ensure that more talented and gifted women can get into the top jobs in companies across the UK.', 'This report recommends that UK listed companies in the FTSE 100 should be aiming for a minimum of 25% female board member representation by 2015. It also recommends for government that FTSE 350 companies should be setting their own, challenging targets. The report says that companies should set targets for 2013 and 2015 to ensure that more talented and gifted women can get into the top jobs in companies across the UK.', 'This report recommends that UK listed companies in the FTSE 100 should be aiming for a minimum of 25% female board member representation by 2015. It also recommends for government that FTSE 350 companies should be setting their own, challenging targets. The report says that companies should set targets for 2013 and 2015 to ensure that more talented and gifted women can get into the top jobs in companies across the UK.', 'UK', 'climate', 'in_force', '2011-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_19', ARRAY['uk', 'mandatory', 'sdg5', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bdaa850b-b865-54ce-ab1d-c1f15b11611b', 'UK Corporate governance in central government departments: Code', 'Corporate governance in central government departments: Code of good practice, 2011', 'Corporate governance is the way in which organisations are directed and controlled. Good corporate governance is vital to effective financial and risk management. The corporate governance code draws on best practice in the public, private and charity sectors. The code incorporates the protocol on enhanced departmental boards, which sets out government policy in this area. Significant changes include the requirement for the Secretary of State to chair the departmental board and a board composition that enhances the role of non-executive board members bringing knowledge and  experience from senior positions in large and complex organisations outside government. The code provides for a ‘comply or explain’ approach, whereby a department can depart from the code’s provisions provided the reasons are explained in its annual governance statement accompanying the department’s accounts. The guidance is optional and does not require compliance or explanation. The principles outlined in the code will also prove useful for other parts of central government and they are encouraged to apply arrangements suitably adapted for their organisation. The code and guidance are intended to be living documents and will evolve as practice develops.', 'Corporate governance is the way in which organisations are directed and controlled. Good corporate governance is vital to effective financial and risk management. The corporate governance code draws on best practice in the public, private and charity sectors. The code incorporates the protocol on enhanced departmental boards, which sets out government policy in this area. Significant changes include the requirement for the Secretary of State to chair the departmental board and a board composition that enhances the role of non-executive board members bringing knowledge and  experience from senior positions in large and complex organisations outside government. The code provides for a ‘comply or explain’ approach, whereby a department can depart from the code’s provisions provided the reasons are explained in its annual governance statement accompanying the department’s accounts. The guidance is optional and does not require compliance or explanation. The principles outlined in the code will also prove useful for other parts of central government and they are encouraged to apply arrangements suitably adapted for their organisation. The code and guidance are intended to be living documents and will evolve as practice develops.', 'Corporate governance is the way in which organisations are directed and controlled. Good corporate governance is vital to effective financial and risk management. The corporate governance code draws on best practice in the public, private and charity sectors. The code incorporates the protocol on enhanced departmental boards, which sets out government policy in this area. Significant changes include the requirement for the Secretary of State to chair the departmental board and a board composition that enhances the role of non-executive board members bringing knowledge and  experience from senior positions in large and complex organisations outside government. The code provides for a ‘comply or explain’ approach, whereby a department can depart from the code’s provisions provided the reasons are explained in its annual governance statement accompanying the department’s accounts. The guidance is optional and does not require compliance or explanation. The principles outlined in the code will also prove useful for other parts of central government and they are encouraged to apply arrangements suitably adapted for their organisation. The code and guidance are intended to be living documents and will evolve as practice develops.', 'UK', 'governance', 'in_force', '2011-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_43', ARRAY['other sustainability policy', 'uk', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c5049a47-c16b-5866-aa73-de12fc96de95', 'UK Cutting Clutter. Combating Clutter in Annual Reports', 'Cutting Clutter. Combating Clutter in Annual Reports, 2011', 'The report provides preparers of annual reports with practical aids for reducing clutter, giving ideas for how disclosures might look without the clutter, and factors to consider when planning the annual report process.', 'The report provides preparers of annual reports with practical aids for reducing clutter, giving ideas for how disclosures might look without the clutter, and factors to consider when planning the annual report process.', 'The report provides preparers of annual reports with practical aids for reducing clutter, giving ideas for how disclosures might look without the clutter, and factors to consider when planning the annual report process.', 'UK', 'climate', 'in_force', '2011-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_80', ARRAY['uk', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2f9ee98a-ba20-5500-abf4-06eca20920db', 'UK Bribery Act', 'Bribery Act, 2010', 'The UK Bribery Act 2010 establishes company liability for corrupt acts committed by persons acting on behalf of the company. The Act prohibits bribery of public officials and business-to-business bribery. With global jurisdiction, companies can be held liable in the UK for acts of corruption committed by employees, agents or subsidiaries anywhere in the world. Unlike the Foreign Corrupt Practices Act (FCPA), the Bribery Act does not distinguish between small and large bribery payments, meaning facilitation payments are prohibited.', 'The UK Bribery Act 2010 establishes company liability for corrupt acts committed by persons acting on behalf of the company. The Act prohibits bribery of public officials and business-to-business bribery. With global jurisdiction, companies can be held liable in the UK for acts of corruption committed by employees, agents or subsidiaries anywhere in the world. Unlike the Foreign Corrupt Practices Act (FCPA), the Bribery Act does not distinguish between small and large bribery payments, meaning facilitation payments are prohibited.', 'The UK Bribery Act 2010 establishes company liability for corrupt acts committed by persons acting on behalf of the company. The Act prohibits bribery of public officials and business-to-business bribery. With global jurisdiction, companies can be held liable in the UK for acts of corruption committed by employees, agents or subsidiaries anywhere in the world. Unlike the Foreign Corrupt Practices Act (FCPA), the Bribery Act does not distinguish between small and large bribery payments, meaning facilitation payments are prohibited.', 'UK', 'governance', 'in_force', '2010-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_15', ARRAY['uk', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d75f3ca5-64e2-5d67-a6dd-887be7fe14be', 'UK Governing for Success. A Code of Governance', 'Governing for Success. A Code of Governance and Good Practice for credit unions in Great Britain, 2010', 'This instrument presents a Code of Governance and Good Practice for credit unions in Great Britain.', 'This instrument presents a Code of Governance and Good Practice for credit unions in Great Britain.', 'This instrument presents a Code of Governance and Good Practice for credit unions in Great Britain.', 'UK', 'governance', 'in_force', '2010-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_31', ARRAY['other sustainability policy', 'uk', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0473d697-fb86-557f-b7cf-5a0431cfbd69', 'UK Corporate Governance Guidance and Principles for Unlisted Companies', 'Corporate Governance Guidance and Principles for Unlisted Companies in the UK, 2010', 'This IoD and ecoDa initiative offers a corporate governance agenda for unlisted companies in the UK.', 'This IoD and ecoDa initiative offers a corporate governance agenda for unlisted companies in the UK.', 'This IoD and ecoDa initiative offers a corporate governance agenda for unlisted companies in the UK.', 'UK', 'governance', 'in_force', '2010-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_41', ARRAY['guidance_frameworks', 'uk', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c3900b2b-33b9-53c4-b2ec-9838d93663a2', 'UK Good Governance: A Code for the Voluntary', 'Good Governance: A Code for the Voluntary and Community Sector, 2010', 'The principles of good governance have been designed to be valid for the entire voluntary and community sector. Given the diversity of the sector, the good governance characteristics may not be applicable to every organisation. This Code recognises that all organisations should (and frequently must) follow principles and practices that fully recognise diversity in all its forms.', 'The principles of good governance have been designed to be valid for the entire voluntary and community sector. Given the diversity of the sector, the good governance characteristics may not be applicable to every organisation. This Code recognises that all organisations should (and frequently must) follow principles and practices that fully recognise diversity in all its forms.', 'The principles of good governance have been designed to be valid for the entire voluntary and community sector. Given the diversity of the sector, the good governance characteristics may not be applicable to every organisation. This Code recognises that all organisations should (and frequently must) follow principles and practices that fully recognise diversity in all its forms.', 'UK', 'governance', 'in_force', '2010-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_45', ARRAY['other sustainability policy', 'uk', 'regulations', 'sdg11', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0b30056b-ad30-5ece-859d-b67efc6f1188', 'UK AIC Code of Corporate Governance', 'The AIC Code of Corporate Governance, 2010', 'This document provides a framework of best practice for Member companies.', 'This document provides a framework of best practice for Member companies.', 'This document provides a framework of best practice for Member companies.', 'UK', 'governance', 'in_force', '2010-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_56', ARRAY['uk', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cd0ae25d-4e51-52bc-b8f3-28a105058121', 'UK Audit Firm Governance Code', 'The Audit Firm Governance Code, 2010', 'The Audit Firm Governance Code (the Code) is intended to assist in promoting continuing confidence and choice in the market for the audit of listed companies and should be relevant to everyone who sees audit as playing a vital role in a market economy.  The primary purpose of the Code is to provide a formal benchmark of good governance practice against which firms which audit listed companies can report for the benefit of shareholders in such companies.', 'The Audit Firm Governance Code (the Code) is intended to assist in promoting continuing confidence and choice in the market for the audit of listed companies and should be relevant to everyone who sees audit as playing a vital role in a market economy.  The primary purpose of the Code is to provide a formal benchmark of good governance practice against which firms which audit listed companies can report for the benefit of shareholders in such companies.', 'The Audit Firm Governance Code (the Code) is intended to assist in promoting continuing confidence and choice in the market for the audit of listed companies and should be relevant to everyone who sees audit as playing a vital role in a market economy.  The primary purpose of the Code is to provide a formal benchmark of good governance practice against which firms which audit listed companies can report for the benefit of shareholders in such companies.', 'UK', 'climate', 'in_force', '2010-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_58', ARRAY['uk', 'regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2f264ee0-8bad-535f-b9a2-14702606f15d', 'UK Equality Act', 'Equality Act 2010', 'The Act is comprehensive, its objective is to reduce socio-economic inequalities but covers a series of prohibited conduct in regards to inequality (discrimination and harassment) and sets out terms/ regulations for work equality. Includes disclosure requirements for discussions about pay.', 'The Act is comprehensive, its objective is to reduce socio-economic inequalities but covers a series of prohibited conduct in regards to inequality (discrimination and harassment) and sets out terms/ regulations for work equality. Includes disclosure requirements for discussions about pay.', 'The Act is comprehensive, its objective is to reduce socio-economic inequalities but covers a series of prohibited conduct in regards to inequality (discrimination and harassment) and sets out terms/ regulations for work equality. Includes disclosure requirements for discussions about pay.', 'UK', 'social', 'in_force', '2010-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_70', ARRAY['sdg10', 'uk', 'regulations', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d15b4395-20bd-531a-91a5-c76a4930e655', 'UK 2009 Review of the Combined Code: Final Report', '2009 Review of the Combined Code: Final Report', 'The purpose of the Code is to promote good governance in the belief that this will support the long-term success of the company. It should not be viewed as a compliance exercise by companies or investors.', 'The purpose of the Code is to promote good governance in the belief that this will support the long-term success of the company. It should not be viewed as a compliance exercise by companies or investors.', 'The purpose of the Code is to promote good governance in the belief that this will support the long-term success of the company. It should not be viewed as a compliance exercise by companies or investors.', 'UK', 'climate', 'in_force', '2009-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_29', ARRAY['uk', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('141ef92d-0c50-5b18-bfb1-56b6c5b8c782', 'review of corporate governance in UK banks', 'A review of corporate governance in UK banks and other financial industry entities (The Walker Review), 2009', 'The "comply or explain" approach to guidance and provisions under the Combined Code provides the surest route to better corporate governance practice in BOFIs. The most critical need is for an environment in which the challenge of the executive is expected and achieved in the boardroom before decisions are taken on major risk and strategic issues. The remit and responsibility of board remuneration committees should be extended beyond board members to cover the whole entity. Performance conditions and deferment in respect of variable pay for executive board members and other senior executives should be materially more demanding than previously. The recommended disclosure should ensure that prospective clients know whether a fund manager in pitching for their business operates a model that includes engagement with long-term performance improvement.', 'The "comply or explain" approach to guidance and provisions under the Combined Code provides the surest route to better corporate governance practice in BOFIs. The most critical need is for an environment in which the challenge of the executive is expected and achieved in the boardroom before decisions are taken on major risk and strategic issues. The remit and responsibility of board remuneration committees should be extended beyond board members to cover the whole entity. Performance conditions and deferment in respect of variable pay for executive board members and other senior executives should be materially more demanding than previously. The recommended disclosure should ensure that prospective clients know whether a fund manager in pitching for their business operates a model that includes engagement with long-term performance improvement.', 'The "comply or explain" approach to guidance and provisions under the Combined Code provides the surest route to better corporate governance practice in BOFIs. The most critical need is for an environment in which the challenge of the executive is expected and achieved in the boardroom before decisions are taken on major risk and strategic issues. The remit and responsibility of board remuneration committees should be extended beyond board members to cover the whole entity. Performance conditions and deferment in respect of variable pay for executive board members and other senior executives should be materially more demanding than previously. The recommended disclosure should ensure that prospective clients know whether a fund manager in pitching for their business operates a model that includes engagement with long-term performance improvement.', 'UK', 'governance', 'in_force', '2009-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_32', ARRAY['uk', 'regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c4f4448d-7b52-53ce-9671-387ab51fa90d', 'review of corporate governance in UK banks', 'A review of corporate governance in UK banks and other financial industry entities: Final recommendations (The Walker Review), 2009', 'The need is now to bring corporate governance issues closer to centre stage. Better financial regulation has much to accomplish, but cannot alone satisfactorily assure performance of the major banks. Behavioural improvement is more likely to be achieved through clearer identification of best practice and more effective but, in most areas, non-statutory routes to implementation. Regulation will make BOFIs safer but cannot assure that they will be attractive to investors and thus able to strengthen their balance sheets. Better corporate governance of banks cannot guarantee that there will be no repetition of the recent highly negative experience for the economy and society as a whole.', 'The need is now to bring corporate governance issues closer to centre stage. Better financial regulation has much to accomplish, but cannot alone satisfactorily assure performance of the major banks. Behavioural improvement is more likely to be achieved through clearer identification of best practice and more effective but, in most areas, non-statutory routes to implementation. Regulation will make BOFIs safer but cannot assure that they will be attractive to investors and thus able to strengthen their balance sheets. Better corporate governance of banks cannot guarantee that there will be no repetition of the recent highly negative experience for the economy and society as a whole.', 'The need is now to bring corporate governance issues closer to centre stage. Better financial regulation has much to accomplish, but cannot alone satisfactorily assure performance of the major banks. Behavioural improvement is more likely to be achieved through clearer identification of best practice and more effective but, in most areas, non-statutory routes to implementation. Regulation will make BOFIs safer but cannot assure that they will be attractive to investors and thus able to strengthen their balance sheets. Better corporate governance of banks cannot guarantee that there will be no repetition of the recent highly negative experience for the economy and society as a whole.', 'UK', 'governance', 'in_force', '2009-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_33', ARRAY['guidance_frameworks', 'uk', 'sdg16', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9e778a42-3426-5dd8-9f27-bb1000c57bdd', 'UK how to measure and report your greenhouse gas', 'Guidance on how to measure and report your greenhouse gas emissions, 2009', 'This report explains how to measure greenhouse gas (GHG) emissions and set targets to reduce them. It is intended for all sizes of business and for public and voluntary sector organisations. There are direct benefits to organisations from measuring and reporting as they will benefit from lower energy and resource costs, a better understanding of their exposure to the risks of climate change and a demonstration of leadership which will help strengthen their green credentials in an increasingly environmentally conscious marketplace. A number of organisations are seeking information from their suppliers on greenhouse gas emissions and so many small businesses will increasingly be expected to measure and report on their emissions. Organisations which use this guidance to measure and report are not required to submit reports nor otherwise make the data available to government.', 'This report explains how to measure greenhouse gas (GHG) emissions and set targets to reduce them. It is intended for all sizes of business and for public and voluntary sector organisations. There are direct benefits to organisations from measuring and reporting as they will benefit from lower energy and resource costs, a better understanding of their exposure to the risks of climate change and a demonstration of leadership which will help strengthen their green credentials in an increasingly environmentally conscious marketplace. A number of organisations are seeking information from their suppliers on greenhouse gas emissions and so many small businesses will increasingly be expected to measure and report on their emissions. Organisations which use this guidance to measure and report are not required to submit reports nor otherwise make the data available to government.', 'This report explains how to measure greenhouse gas (GHG) emissions and set targets to reduce them. It is intended for all sizes of business and for public and voluntary sector organisations. There are direct benefits to organisations from measuring and reporting as they will benefit from lower energy and resource costs, a better understanding of their exposure to the risks of climate change and a demonstration of leadership which will help strengthen their green credentials in an increasingly environmentally conscious marketplace. A number of organisations are seeking information from their suppliers on greenhouse gas emissions and so many small businesses will increasingly be expected to measure and report on their emissions. Organisations which use this guidance to measure and report are not required to submit reports nor otherwise make the data available to government.', 'UK', 'climate', 'in_force', '2009-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_79', ARRAY['guidance_frameworks', 'sdg13', 'uk', 'sdg7', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f317a483-788c-5a5c-a53c-50bd0c30d56e', 'UK Climate Change Act', 'Climate Change Act, 2008', 'This Act was introduced to ensure that the UK accounts for all six Kyoto gas groups.', 'This Act was introduced to ensure that the UK accounts for all six Kyoto gas groups.', 'This Act was introduced to ensure that the UK accounts for all six Kyoto gas groups.', 'UK', 'climate', 'in_force', '2008-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_12', ARRAY['sdg13', 'uk', 'regulations', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c2df9045-3a84-5352-848b-2d3992f73f1b', 'UK Combined Code on Corporate Governance (revised', 'The Combined Code on Corporate Governance (revised 2008)', 'This edition of the Code applies to accounting periods beginning on or after 29 June 2008, and takes effect at the same time as new FSA Corporate Governance Rules implementing European requirements relating to audit committees and corporate governance statements.', 'This edition of the Code applies to accounting periods beginning on or after 29 June 2008, and takes effect at the same time as new FSA Corporate Governance Rules implementing European requirements relating to audit committees and corporate governance statements.', 'This edition of the Code applies to accounting periods beginning on or after 29 June 2008, and takes effect at the same time as new FSA Corporate Governance Rules implementing European requirements relating to audit committees and corporate governance statements.', 'UK', 'climate', 'in_force', '2008-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_60', ARRAY['uk', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1ba43a6d-a24f-5ae9-a90c-3c925ffe4fa5', 'UK Disclosure and Transparency in Private Equity', 'Guidelines for Disclosure and Transparency in Private Equity, 2007', 'The guidelines recommend that private equity firms be required to publish a description of their structure and investment approach. UK companies owned by such private equity firms (portfolio companies) must also publish their annual report and accounts on their websites and prepare mid-year updates.', 'The guidelines recommend that private equity firms be required to publish a description of their structure and investment approach. UK companies owned by such private equity firms (portfolio companies) must also publish their annual report and accounts on their websites and prepare mid-year updates.', 'The guidelines recommend that private equity firms be required to publish a description of their structure and investment approach. UK companies owned by such private equity firms (portfolio companies) must also publish their annual report and accounts on their websites and prepare mid-year updates.', 'UK', 'climate', 'in_force', '2007-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_48', ARRAY['guidance_frameworks', 'uk', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ad0474f2-a842-5634-a0c5-5506178a4729', 'UK Equality Act', 'Equality Act, 2006', 'The 2006 Act is a precursor to the Equality Act 2010, which combines all of the equality enactments within Great Britain and provide comparable protections across all equality strands. Those explicitly mentioned by the Equality Act 2006 include age; disability; sex; proposed, commenced or completed gender reassignment; race; religion or belief and sexual orientation.', 'The 2006 Act is a precursor to the Equality Act 2010, which combines all of the equality enactments within Great Britain and provide comparable protections across all equality strands. Those explicitly mentioned by the Equality Act 2006 include age; disability; sex; proposed, commenced or completed gender reassignment; race; religion or belief and sexual orientation.', 'The 2006 Act is a precursor to the Equality Act 2010, which combines all of the equality enactments within Great Britain and provide comparable protections across all equality strands. Those explicitly mentioned by the Equality Act 2006 include age; disability; sex; proposed, commenced or completed gender reassignment; race; religion or belief and sexual orientation.', 'UK', 'social', 'in_force', '2006-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_22', ARRAY['uk', 'regulations', 'mandatory', 'sdg5', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1998fa63-ae9d-5a4f-b49d-1487c5049121', 'UK Good practice suggestions from the Higgs Report', 'Good practice suggestions from the Higgs Report, 2006', 'The Code provides that the remuneration committee should consist exclusively of independent non-executive directors and should comprise at least three or, in the case of smaller companies, two such directors.', 'The Code provides that the remuneration committee should consist exclusively of independent non-executive directors and should comprise at least three or, in the case of smaller companies, two such directors.', 'The Code provides that the remuneration committee should consist exclusively of independent non-executive directors and should comprise at least three or, in the case of smaller companies, two such directors.', 'UK', 'climate', 'in_force', '2006-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_47', ARRAY['mandatory', 'other sustainability policy', 'uk', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b8643134-d732-508d-bbe2-96a66047154d', 'UK Combined Code on Corporate Governance', 'The Combined Code on Corporate Governance, 2006', 'This Code supersedes and replaces the Combined Code issued in 2003. It follows a review by the Financial Reporting Council of the implementation of the Code in 2005 and subsequent consultation on possible amendments to the Code.', 'This Code supersedes and replaces the Combined Code issued in 2003. It follows a review by the Financial Reporting Council of the implementation of the Code in 2005 and subsequent consultation on possible amendments to the Code.', 'This Code supersedes and replaces the Combined Code issued in 2003. It follows a review by the Financial Reporting Council of the implementation of the Code in 2005 and subsequent consultation on possible amendments to the Code.', 'UK', 'climate', 'in_force', '2006-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_78', ARRAY['uk', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6989372a-363a-522c-a212-ac6434f523b8', 'UK Corporate governance in central government departments: Code', 'Corporate governance in central government departments: Code of good practice, 2005', 'The code has been assembled to guide central government departments, focussing on the role of departmental management boards and how they can support ministers and heads of departments.', 'The code has been assembled to guide central government departments, focussing on the role of departmental management boards and how they can support ministers and heads of departments.', 'The code has been assembled to guide central government departments, focussing on the role of departmental management boards and how they can support ministers and heads of departments.', 'UK', 'climate', 'in_force', '2005-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_42', ARRAY['other sustainability policy', 'uk', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7fabefec-c6ac-5b44-91ee-a60509dc426f', 'UK Good Governance: The Code of Governance for the', 'Good Governance: The Code of Governance for the Voluntary and Community Sector, 2005', 'This code is primarily aimed at the trustees of voluntary and community organisations, who have ultimate governance responsibilities. It will help them to lead their organisations through example, and to achieve excellent governance. It is also aimed at chief executives, who provide the bridge between trustees and staff, and have a central role in ensuring good governance.', 'This code is primarily aimed at the trustees of voluntary and community organisations, who have ultimate governance responsibilities. It will help them to lead their organisations through example, and to achieve excellent governance. It is also aimed at chief executives, who provide the bridge between trustees and staff, and have a central role in ensuring good governance.', 'This code is primarily aimed at the trustees of voluntary and community organisations, who have ultimate governance responsibilities. It will help them to lead their organisations through example, and to achieve excellent governance. It is also aimed at chief executives, who provide the bridge between trustees and staff, and have a central role in ensuring good governance.', 'UK', 'governance', 'in_force', '2005-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_46', ARRAY['other sustainability policy', 'uk', 'sdg11', 'voluntary', 'sdg16', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dbaeb4b1-cb33-5301-bc47-c480427698ff', 'UK Internal Control. Revised Guidance for Directors on the', 'Internal Control. Revised Guidance for Directors on the Combined Code, 2005', 'This is an updated version of the Turnbull guidance published by the Financial Reporting Council on 13 October 2005. The updated version took effect for financial years beginning on or after 1 January 2006. In September 2014 it was replaced by ‘Guidance on Risk Management, Internal Control and Related Financial and Business Reporting’ also published by the FRC.', 'This is an updated version of the Turnbull guidance published by the Financial Reporting Council on 13 October 2005. The updated version took effect for financial years beginning on or after 1 January 2006. In September 2014 it was replaced by ‘Guidance on Risk Management, Internal Control and Related Financial and Business Reporting’ also published by the FRC.', 'This is an updated version of the Turnbull guidance published by the Financial Reporting Council on 13 October 2005. The updated version took effect for financial years beginning on or after 1 January 2006. In September 2014 it was replaced by ‘Guidance on Risk Management, Internal Control and Related Financial and Business Reporting’ also published by the FRC.', 'UK', 'climate', 'in_force', '2005-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_52', ARRAY['guidance_frameworks', 'mandatory', 'uk', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e4c9f864-3fbf-5dc0-8227-ce31fbfd62ec', 'UK Pension Scheme Governance - Fit for the 21st', 'Pension Scheme Governance - Fit for the 21st century, 2005', 'This Discussion Paper seeks the views of stakeholders on 22 questions on all aspects of pension scheme governance with a view to ensuring that all schemes – whether defined benefit or defined contribution, trust-based or contract-based – enjoy good governance arrangements that can effectively protect the interests of working people. This will be an important step in helping to restore workers’ confidence in saving for retirement.', 'This Discussion Paper seeks the views of stakeholders on 22 questions on all aspects of pension scheme governance with a view to ensuring that all schemes – whether defined benefit or defined contribution, trust-based or contract-based – enjoy good governance arrangements that can effectively protect the interests of working people. This will be an important step in helping to restore workers’ confidence in saving for retirement.', 'This Discussion Paper seeks the views of stakeholders on 22 questions on all aspects of pension scheme governance with a view to ensuring that all schemes – whether defined benefit or defined contribution, trust-based or contract-based – enjoy good governance arrangements that can effectively protect the interests of working people. This will be an important step in helping to restore workers’ confidence in saving for retirement.', 'UK', 'climate', 'in_force', '2005-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_53', ARRAY['sdg8', 'uk', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d128b823-e962-57fe-9b59-bdc12870c10c', 'UK Occupational Pension Schemes (Investment) Regulations', 'No. 3378 The Occupational Pension Schemes (Investment) Regulations, 2005', 'This statutory instrument outlines Occupational Pension Schemes (Investment) Regulations 2005.', 'This statutory instrument outlines Occupational Pension Schemes (Investment) Regulations 2005.', 'This statutory instrument outlines Occupational Pension Schemes (Investment) Regulations 2005.', 'UK', 'social', 'in_force', '2005-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_77', ARRAY['sdg8', 'uk', 'regulations', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('60d1f27e-3756-50b7-bbf7-a81bc3347a75', 'UK Corporate Governance: A Practical Guide', 'Corporate Governance: A Practical Guide, 2004', 'This guide is intended to provide practical advice to listed companies on how to implement the new Combined Code on Corporate Governance and covers issues such as selecting and developing the board, succession-planning, working effectively as a team, issues that should be addressed by the board to enable the company to reach its full potential (including input to strategy, effective risk management, communicating with shareholders and the development of an integrated approach to corporate social responsibility) and the work of board committees. It is intended that companies quoted on AIM should also find the guide useful even though the Combined Code does not formally apply to them.', 'This guide is intended to provide practical advice to listed companies on how to implement the new Combined Code on Corporate Governance and covers issues such as selecting and developing the board, succession-planning, working effectively as a team, issues that should be addressed by the board to enable the company to reach its full potential (including input to strategy, effective risk management, communicating with shareholders and the development of an integrated approach to corporate social responsibility) and the work of board committees. It is intended that companies quoted on AIM should also find the guide useful even though the Combined Code does not formally apply to them.', 'This guide is intended to provide practical advice to listed companies on how to implement the new Combined Code on Corporate Governance and covers issues such as selecting and developing the board, succession-planning, working effectively as a team, issues that should be addressed by the board to enable the company to reach its full potential (including input to strategy, effective risk management, communicating with shareholders and the development of an integrated approach to corporate social responsibility) and the work of board committees. It is intended that companies quoted on AIM should also find the guide useful even though the Combined Code does not formally apply to them.', 'UK', 'governance', 'in_force', '2004-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_44', ARRAY['uk', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('76579853-1177-563f-a2b4-722edf81804b', 'UK Combined Code on Corporate Governance', 'The Combined Code on Corporate Governance, 2003', 'This Code supersedes and replaces the Combined Code issued by the Hampel Committee on Corporate Governance in June 1998. It derives from a review of the role and effectiveness of non-executive directors by Derek Higgs and a review of audit committees by a group led by Sir Robert Smith.', 'This Code supersedes and replaces the Combined Code issued by the Hampel Committee on Corporate Governance in June 1998. It derives from a review of the role and effectiveness of non-executive directors by Derek Higgs and a review of audit committees by a group led by Sir Robert Smith.', 'This Code supersedes and replaces the Combined Code issued by the Hampel Committee on Corporate Governance in June 1998. It derives from a review of the role and effectiveness of non-executive directors by Derek Higgs and a review of audit committees by a group led by Sir Robert Smith.', 'UK', 'climate', 'in_force', '2003-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_59', ARRAY['uk', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e972ad17-4584-5054-8e8e-a2f2439d5774', 'UK Review of the role and effectiveness of non-executive', 'Review of the role and effectiveness of non-executive directors  (Higg''s Review), 2003', 'In April 2002 the Secretary of State, Patricia Hewitt, and the Chancellor, Gordon Brown, appointed Derek Higgs to lead a short independent review of the role and effectiveness of non-executive directors. Derek Higgs published his report on 20th January 2003. The report includes: guidance for non-executive directors, guidance for the chairman and a proposal for a revised combined code. The full report can be accessed by clicking on the appropriate document link on the right of the screen or alternatively you can click on the link for the relevant section of the report you are interested in. The Government warmly welcomed the recommendations of the Higgs Review. To view the Government''s press release responding to the Higgs Review please click on the appropriate link on the right of the screen.', 'In April 2002 the Secretary of State, Patricia Hewitt, and the Chancellor, Gordon Brown, appointed Derek Higgs to lead a short independent review of the role and effectiveness of non-executive directors. Derek Higgs published his report on 20th January 2003. The report includes: guidance for non-executive directors, guidance for the chairman and a proposal for a revised combined code. The full report can be accessed by clicking on the appropriate document link on the right of the screen or alternatively you can click on the link for the relevant section of the report you are interested in. The Government warmly welcomed the recommendations of the Higgs Review. To view the Government''s press release responding to the Higgs Review please click on the appropriate link on the right of the screen.', 'In April 2002 the Secretary of State, Patricia Hewitt, and the Chancellor, Gordon Brown, appointed Derek Higgs to lead a short independent review of the role and effectiveness of non-executive directors. Derek Higgs published his report on 20th January 2003. The report includes: guidance for non-executive directors, guidance for the chairman and a proposal for a revised combined code. The full report can be accessed by clicking on the appropriate document link on the right of the screen or alternatively you can click on the link for the relevant section of the report you are interested in. The Government warmly welcomed the recommendations of the Higgs Review. To view the Government''s press release responding to the Higgs Review please click on the appropriate link on the right of the screen.', 'UK', 'climate', 'in_force', '2003-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_63', ARRAY['guidance_frameworks', 'uk', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ea147e6b-288d-52f0-87d6-4b628f649dd0', 'UK Audit Committees. Combined Code Guidance. A Report', 'Audit Committees. Combined Code Guidance. A Report and proposed Guidance by the FRC-appointed group chaired by Sir Robert Smith (the Smith Report)', 'The aim of the report is to clarify the role and responsibilities of audit committees and to develop the Combined Code guidance. The report includes specimen terms of reference for an audit committee and an outline of the section to be included in a company’s annual report on the activities of the audit committee. Guidance from the Smith report is now contained in the FRC Guidance on Audit Committees and the Combined Code has now been superseded by the UK Corporate Governance Code in respect of accounting periods beginning on or after 29 June 2010.', 'The aim of the report is to clarify the role and responsibilities of audit committees and to develop the Combined Code guidance. The report includes specimen terms of reference for an audit committee and an outline of the section to be included in a company’s annual report on the activities of the audit committee. Guidance from the Smith report is now contained in the FRC Guidance on Audit Committees and the Combined Code has now been superseded by the UK Corporate Governance Code in respect of accounting periods beginning on or after 29 June 2010.', 'The aim of the report is to clarify the role and responsibilities of audit committees and to develop the Combined Code guidance. The report includes specimen terms of reference for an audit committee and an outline of the section to be included in a company’s annual report on the activities of the audit committee. Guidance from the Smith report is now contained in the FRC Guidance on Audit Committees and the Combined Code has now been superseded by the UK Corporate Governance Code in respect of accounting periods beginning on or after 29 June 2010.', 'UK', 'climate', 'in_force', '2002-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_34', ARRAY['guidance_frameworks', 'uk', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('376d4605-d691-58f3-b10f-9a7a09cc4a31', 'UK Review of the role and effectiveness of non-executive', 'Review of the role and effectiveness of non-executive directors. Consultation Paper, 2002', 'This consultation document request feedback on the following questions: (1) What role should non-executive directors perform, and how does this compare to the present position? (2) What knowledge, skills and attributes are needed, and what can be done to attract, recruit and appoint the best people to non- executive roles? (3) Do existing structures and procedures facilitate effective performance by non-executive directors? (4) Do existing relationships with shareholders or others need to be strengthened? (5) How can non-executive directors best be supported to perform their role? In relation to all of the above we need to consider the following two aspects: (6) In what ways is the position different for smaller listed companies? (7) What can we learn from international experience?.', 'This consultation document request feedback on the following questions: (1) What role should non-executive directors perform, and how does this compare to the present position? (2) What knowledge, skills and attributes are needed, and what can be done to attract, recruit and appoint the best people to non- executive roles? (3) Do existing structures and procedures facilitate effective performance by non-executive directors? (4) Do existing relationships with shareholders or others need to be strengthened? (5) How can non-executive directors best be supported to perform their role? In relation to all of the above we need to consider the following two aspects: (6) In what ways is the position different for smaller listed companies? (7) What can we learn from international experience?.', 'This consultation document request feedback on the following questions: (1) What role should non-executive directors perform, and how does this compare to the present position? (2) What knowledge, skills and attributes are needed, and what can be done to attract, recruit and appoint the best people to non- executive roles? (3) Do existing structures and procedures facilitate effective performance by non-executive directors? (4) Do existing relationships with shareholders or others need to be strengthened? (5) How can non-executive directors best be supported to perform their role? In relation to all of the above we need to consider the following two aspects: (6) In what ways is the position different for smaller listed companies? (7) What can we learn from international experience?.', 'UK', 'climate', 'in_force', '2002-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_54', ARRAY['other sustainability policy', 'uk', 'regulations', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0a101847-3290-57bd-89d3-832d1823dcc4', 'UK Hermes Principles', 'The Hermes Principles, 2002', 'This document sets out principles to address a simple question: ‘What should owners expect from UK public companies and what should these companies expect from their owners?', 'This document sets out principles to address a simple question: ‘What should owners expect from UK public companies and what should these companies expect from their owners?', 'This document sets out principles to address a simple question: ‘What should owners expect from UK public companies and what should these companies expect from their owners?', 'UK', 'governance', 'in_force', '2002-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_62', ARRAY['guidance_frameworks', 'voluntary', 'other sustainability policy', 'uk']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3ab48b92-25c5-5026-b98c-bfde99cef105', 'UK Code of Good Practice. Institutional Investors and Corporate', 'Code of Good Practice. Institutional Investors and Corporate Governance, 2001', 'A recommendation to all AUTIF members to adopt a clear and considered policy towards their responsibilities as shareholders.', 'A recommendation to all AUTIF members to adopt a clear and considered policy towards their responsibilities as shareholders.', 'A recommendation to all AUTIF members to adopt a clear and considered policy towards their responsibilities as shareholders.', 'UK', 'governance', 'in_force', '2001-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_40', ARRAY['uk', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7529a73e-1d43-50f5-841a-d92b386b1152', 'UK Local Government Pension Scheme (Management and Investment', 'The Local Government Pension Scheme (Management and Investment of Funds) (Amendment) Regulations 1999', 'The regulations state that an administering authority must, after consultation with such persons as they consider appropriate, prepare, maintain and publish a written statement of the principles governing their decisions about investments. The statement must cover their policy on a number of key criteria including - (c) risk; (f) the extent (if at all) to which social, environmental and ethical considerations are taken into account in the selection, retention and realization of investment.', 'The regulations state that an administering authority must, after consultation with such persons as they consider appropriate, prepare, maintain and publish a written statement of the principles governing their decisions about investments. The statement must cover their policy on a number of key criteria including - (c) risk; (f) the extent (if at all) to which social, environmental and ethical considerations are taken into account in the selection, retention and realization of investment.', 'The regulations state that an administering authority must, after consultation with such persons as they consider appropriate, prepare, maintain and publish a written statement of the principles governing their decisions about investments. The statement must cover their policy on a number of key criteria including - (c) risk; (f) the extent (if at all) to which social, environmental and ethical considerations are taken into account in the selection, retention and realization of investment.', 'UK', 'governance', 'in_force', '1999-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_28', ARRAY['mandatory', 'other sustainability policy', 'uk', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
